def simple_confounded_graph():
    return nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])


def iv_graph():
    # U is an unobserved confounder; Z is a valid instrument.
    return nx.DiGraph([("Z", "X"), ("X", "Y"), ("U", "X"), ("U", "Y")])


def frontdoor_graph():
    return nx.DiGraph([("X", "M"), ("M", "Y"), ("U", "X"), ("U", "Y")])


def mediation_graph():
    return nx.DiGraph(
        [("X", "M"), ("M", "Y"), ("X", "Y"), ("Z", "X"), ("Z", "Y")]
    )


