import networkx as nx

from dowhy.causal_identifier.adjustment_set import AdjustmentSet
from dowhy.causal_identifier.backdoor import Backdoor, HittingSetAlgorithm, NodePair, Path


class TestPath:
    def test_initial_state_is_unknown_and_unconditional(self):
        path = Path()

        assert path.is_blocked() is None
        assert path.get_condition_vars() == set()

    def test_update_with_unblocked_path_records_intermediate_nodes(self):
        path = Path()

        path.update(["X", "A", "B", "Y"], is_blocked=False)

        assert path.is_blocked() is False
        assert path.get_condition_vars() == {"A", "B"}

    def test_update_with_blocked_path_keeps_condition_vars_empty(self):
        path = Path()

        path.update(["X", "A", "Y"], is_blocked=True)

        assert path.is_blocked() is True
        assert path.get_condition_vars() == set()

    def test_repeated_unblocked_updates_union_condition_vars(self):
        path = Path()

        path.update(["X", "A", "Y"], is_blocked=False)
        path.update(["X", "B", "Y"], is_blocked=False)

        assert path.get_condition_vars() == {"A", "B"}

    def test_str_mentions_blocking_variables(self):
        path = Path()
        path.update(["X", "A", "Y"], is_blocked=False)

        rendered = str(path)

        assert "Blocked: False" in rendered
        assert "A" in rendered

    def test_str_of_blocked_path_has_no_condition_suggestion(self):
        path = Path()
        path.update(["X", "A", "Y"], is_blocked=True)

        assert str(path) == "Blocked: True\n"


class TestNodePair:
    def test_initial_state(self):
        node_pair = NodePair("X", "Y")

