class TestHittingSetAlgorithm:
    def test_num_sets_returns_number_of_backdoor_paths(self):
        algorithm = HittingSetAlgorithm([{"A"}, {"B"}, {"C"}])

        assert algorithm.num_sets() == 3

    def test_find_set_returns_var_hitting_every_set(self):
        # B appears in all three sets and is therefore the unique best choice.
        algorithm = HittingSetAlgorithm([{"A", "B"}, {"B", "C"}, {"B", "D"}])

        hitting_set = algorithm.find_set()

        assert hitting_set == {"B"}
        assert all(hitting_set.intersection(s) for s in [{"A", "B"}, {"B", "C"}, {"B", "D"}])

    def test_find_set_ignores_colliders(self):
        algorithm = HittingSetAlgorithm([{"A"}, {"B"}], colliders={"A"})

        assert algorithm.find_set() == {"B"}

    def test_find_set_on_empty_collection_is_empty(self):
        algorithm = HittingSetAlgorithm([])

        assert algorithm.num_sets() == 0
        assert algorithm.find_set() == set()


class TestBackdoor:
    def test_simple_confounder_yields_backdoor_set(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        adjustment_set = backdoor_sets[0]
        assert adjustment_set.get_adjustment_type() == AdjustmentSet.BACKDOOR
        assert set(adjustment_set.get_adjustment_variables()) == {"Z"}
        assert adjustment_set.get_num_paths_blocked_by_observed_nodes() == 1

    def test_no_backdoor_paths_yields_no_adjustment_sets(self):
        graph = nx.DiGraph([("X", "Y")])

        assert Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars() == []

    def test_collider_paths_are_not_treated_as_backdoor_paths(self):
        # X -> C <- Y is a collider path, not a confounding path.
        graph = nx.DiGraph([("X", "Y"), ("X", "C"), ("Y", "C")])

        assert Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars() == []

    def test_chain_confounder_is_blocked_by_an_intermediate_ancestor(self):
        graph = nx.DiGraph([("B", "A"), ("A", "X"), ("B", "Y"), ("X", "Y")])

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        adjustment_variables = set(backdoor_sets[0].get_adjustment_variables())
        # Either node on the X <- A <- B -> Y path is a valid adjustment choice.
        assert adjustment_variables
        assert adjustment_variables <= {"A", "B"}

    def test_two_independent_confounders_are_both_selected(self):
        graph = nx.DiGraph(
            [("A", "X"), ("A", "Y"), ("B", "X"), ("B", "Y"), ("X", "Y")]
        )

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        assert set(backdoor_sets[0].get_adjustment_variables()) == {"A", "B"}

    def test_is_backdoor_detects_incoming_edge_from_first_path_node(self):
        graph = nx.DiGraph([("Z", "X"), ("X", "Y")])
        backdoor = Backdoor(graph, ["X"], ["Y"])

        assert backdoor.is_backdoor(["X", "Z", "Y"]) is True
        assert backdoor.is_backdoor(["Y", "Z", "X"]) is False
        assert backdoor.is_backdoor(["X"]) is False
import networkx as nx
import pytest

from dowhy.causal_identifier.efficient_backdoor import (
    EXCEPTION_COND_NO_OPT,
    EXCEPTION_NO_ADJ,
    EfficientBackdoor,
)
from dowhy.graph import check_valid_backdoor_set


def simple_confounded_graph():
    return nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])


def diamond_graph():
    # Two alternative ways of blocking the confounding: {A, B} or the cheaper {C}.
    return nx.DiGraph(
        [("A", "X"), ("B", "X"), ("A", "C"), ("B", "C"), ("C", "Y"), ("X", "Y")]
    )


