    def test_rejects_multidimensional_outcome(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="one dimensional outcomes"):
            EfficientBackdoor(graph, ["X"], ["Y", "Z"], ["X", "Y", "Z"])

    def test_rejects_non_positive_costs(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="All costs must be positive"):
            EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y", "Z"], costs=[("X", {"cost": 0})])

