import pytest

from dowhy.causal_identifier.id_identifier import IDExpression, IDIdentifier, identify_effect_id
from dowhy.utils.ordered_set import OrderedSet


class TestIDExpression:
    def test_product_and_sum_accumulate(self):
        expression = IDExpression()
        predictor = {"outcome_vars": OrderedSet(["Y"]), "condition_vars": OrderedSet(["X"])}

        expression.add_product(predictor)
        expression.add_sum({"Z", "W"})

        assert expression.get_val("prod") == [predictor]
        assert set(expression.get_val("sum")) == {"Z", "W"}

    def test_get_val_rejects_unknown_return_type(self):
        expression = IDExpression()

        with pytest.raises(ValueError, match="Provide correct return type"):
            expression.get_val("unknown")

    def test_str_of_single_predictor_includes_conditioning(self):
        expression = IDExpression()
        expression.add_product(
            {"outcome_vars": OrderedSet(["Y"]), "condition_vars": OrderedSet(["X", "Z"])}
        )

        assert str(expression) == "Predictor: P(Y|X,Z)"

    def test_str_of_single_predictor_without_conditioning(self):
        expression = IDExpression()
        expression.add_product({"outcome_vars": OrderedSet(["Y"]), "condition_vars": OrderedSet([])})

        assert str(expression) == "Predictor: P(Y)"

    def test_str_of_nested_expression_renders_marginalization(self):
        inner = IDExpression()
        inner.add_product(
            {"outcome_vars": OrderedSet(["A"]), "condition_vars": OrderedSet(["B"])}
        )
        outer = IDExpression()
        outer.add_product(inner)
        outer.add_sum({"Z"})

        assert str(outer) == "Sum over {Z}:\n\tPredictor: P(A|B)"

    def test_str_with_missing_nested_product_reports_unidentifiable(self):
        expression = IDExpression()
        expression.add_product(None)

        assert str(expression) == "The graph is not identifiable."


class TestIdentifyEffectID:
    def test_simple_confounding_graph_marginalizes_confounder(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        expression = identify_effect_id(graph, "X", "Y")

        assert str(expression) == "Sum over {Z}:\n\tPredictor: P(Z)\n\tPredictor: P(Y|Z,X)"
        assert expression.get_val("sum") == []
        assert len(expression.get_val("prod")) == 1

    def test_direct_effect_graph_needs_only_conditioning(self):
        graph = nx.DiGraph([("X", "Y")])

        expression = identify_effect_id(graph, "X", "Y")

        assert str(expression) == "Predictor: P(Y|X)"
        assert expression.get_val("sum") == []

    def test_accepts_list_valued_treatment(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        expression = identify_effect_id(graph, ["X"], ["Y"])

        assert "P(Y|Z,X)" in str(expression)

    def test_cyclic_graph_raises_value_error(self):
        graph = nx.DiGraph([("X", "Y"), ("Y", "X")])

        with pytest.raises(ValueError, match="directed acyclic graph"):
            identify_effect_id(graph, "X", "Y")


class TestIDIdentifier:
    def test_identify_effect_matches_function(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])
        identifier = IDIdentifier()

        via_class = identifier.identify_effect(graph, "X", "Y", ["X", "Y", "Z"])
        via_function = identify_effect_id(graph, "X", "Y")

        assert str(via_class) == str(via_function)

    def test_observed_nodes_are_not_used_by_id_algorithm(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])
        identifier = IDIdentifier()

        expression = identifier.identify_effect(graph, "X", "Y", ["X", "Y"])

        # The ID algorithm operates on the full graph, including the latent Z.
        assert "P(Z)" in str(expression)
