def diamond_graph():
    # {A, B}, {A, C}, {B, C} and {C} are all valid adjustment sets.
    return nx.DiGraph(
        [("A", "X"), ("B", "X"), ("A", "C"), ("B", "C"), ("C", "Y"), ("X", "Y")]
    )


def as_frozensets(adjustment_sets):
    return {frozenset(s.get_adjustment_variables()) for s in adjustment_sets}


class TestIdentifyBackdoorMethods:
    def test_default_returns_largest_then_minimal_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_DEFAULT,
        )

        assert as_frozensets(adjustment_sets) == {frozenset({"A", "B", "C"}), frozenset({"C"})}
        assert all(s.get_adjustment_type() == "backdoor" for s in adjustment_sets)

    def test_minimal_adjustment_returns_smallest_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_MIN,
        )

        assert len(adjustment_sets) == 1
        assert set(adjustment_sets[0].get_adjustment_variables()) == {"C"}

    def test_maximal_adjustment_returns_largest_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_MAX,
        )

        assert len(adjustment_sets) == 1
        assert set(adjustment_sets[0].get_adjustment_variables()) == {"A", "B", "C"}

    def test_exhaustive_search_returns_every_valid_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
        )

        assert as_frozensets(adjustment_sets) == {
            frozenset({"A", "B"}),
            frozenset({"A", "B", "C"}),
            frozenset({"A", "C"}),
            frozenset({"B", "C"}),
            frozenset({"C"}),
        }

    def test_empty_set_is_returned_when_graph_needs_no_adjustment(self):
        for method in (
            BackdoorAdjustment.BACKDOOR_DEFAULT,
            BackdoorAdjustment.BACKDOOR_MIN,
            BackdoorAdjustment.BACKDOOR_MAX,
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
        ):
            adjustment_sets = identify_backdoor(
                nx.DiGraph([("X", "Y")]), ["X"], ["Y"], ["X", "Y"], method
            )

            assert len(adjustment_sets) == 1
            assert adjustment_sets[0].get_adjustment_variables() == set()


