        graph.add_node("W")
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y", "Z", "W"])

        with pytest.raises(ValueError) as excinfo:
            efficient.optimal_adj_set()

        assert excinfo.value.args[0] == EXCEPTION_COND_NO_OPT


class TestMincutHelpers:
    def test_smallest_mincut_operator_yields_backdoor_set(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        smallest_mincut = efficient.compute_smallest_mincut()

        assert "Y''" in smallest_mincut
        assert efficient.h_operator(smallest_mincut) == {"Z"}

    def test_h_operator_selects_nodes_with_only_primal_vertex_in_cut(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.h_operator({"Z'", "Y''"}) == {"Z"}
        assert efficient.h_operator({"Z''"}) == set()

    def test_unblocked_returns_boundary_of_treatment_component(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])
        h1 = efficient.build_H1()

        unblocked = efficient.unblocked(h1, {"Z"})

        assert unblocked == {"Z"}

import networkx as nx
import pytest

from dowhy.causal_identifier.auto_identifier import (
    BackdoorAdjustment,
    identify_backdoor,
    identify_frontdoor,
    identify_mediation,
)


def diamond_graph():
    # {A, B}, {A, C}, {B, C} and {C} are all valid adjustment sets.
    return nx.DiGraph(
        [("A", "X"), ("B", "X"), ("A", "C"), ("B", "C"), ("C", "Y"), ("X", "Y")]
    )


def as_frozensets(adjustment_sets):
    return {frozenset(s.get_adjustment_variables()) for s in adjustment_sets}


class TestIdentifyBackdoorMethods:
    def test_default_returns_largest_then_minimal_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_DEFAULT,
        )

        assert as_frozensets(adjustment_sets) == {frozenset({"A", "B", "C"}), frozenset({"C"})}
        assert all(s.get_adjustment_type() == "backdoor" for s in adjustment_sets)

    def test_minimal_adjustment_returns_smallest_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_MIN,
        )

        assert len(adjustment_sets) == 1
        assert set(adjustment_sets[0].get_adjustment_variables()) == {"C"}

    def test_maximal_adjustment_returns_largest_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_MAX,
        )

        assert len(adjustment_sets) == 1
        assert set(adjustment_sets[0].get_adjustment_variables()) == {"A", "B", "C"}

    def test_exhaustive_search_returns_every_valid_set(self):
        adjustment_sets = identify_backdoor(
            diamond_graph(),
            ["X"],
            ["Y"],
            ["X", "Y", "A", "B", "C"],
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
        )

        assert as_frozensets(adjustment_sets) == {
            frozenset({"A", "B"}),
            frozenset({"A", "B", "C"}),
            frozenset({"A", "C"}),
            frozenset({"B", "C"}),
            frozenset({"C"}),
        }

    def test_empty_set_is_returned_when_graph_needs_no_adjustment(self):
        for method in (
            BackdoorAdjustment.BACKDOOR_DEFAULT,
            BackdoorAdjustment.BACKDOOR_MIN,
            BackdoorAdjustment.BACKDOOR_MAX,
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
        ):
            adjustment_sets = identify_backdoor(
                nx.DiGraph([("X", "Y")]), ["X"], ["Y"], ["X", "Y"], method
            )

            assert len(adjustment_sets) == 1
            assert adjustment_sets[0].get_adjustment_variables() == set()


class TestIdentifyBackdoorOptions:
    def test_direct_effect_keeps_mediators_eligible(self):
        graph = nx.DiGraph(
            [("Z", "X"), ("Z", "Y"), ("X", "Y"), ("X", "M"), ("M", "Y")]
        )
        observed = ["X", "Y", "Z", "M"]

        total_effect_sets = identify_backdoor(
            graph, ["X"], ["Y"], observed, BackdoorAdjustment.BACKDOOR_MIN
        )
        direct_effect_sets = identify_backdoor(
            graph,
            ["X"],
            ["Y"],
            observed,
            BackdoorAdjustment.BACKDOOR_MIN,
            direct_effect=True,
        )

        assert set(total_effect_sets[0].get_adjustment_variables()) == {"Z"}
        assert set(direct_effect_sets[0].get_adjustment_variables()) == {"Z", "M"}

    def test_include_unobserved_allows_latent_variables(self):
        graph = nx.DiGraph([("U", "X"), ("U", "Y"), ("X", "Y")])

        observed_only = identify_backdoor(
            graph,
            ["X"],
            ["Y"],
            ["X", "Y"],
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
        )
        including_unobserved = identify_backdoor(
            graph,
            ["X"],
            ["Y"],
            ["X", "Y"],
            BackdoorAdjustment.BACKDOOR_EXHAUSTIVE,
            include_unobserved=True,
        )

        assert observed_only == []
        assert as_frozensets(including_unobserved) == {frozenset({"U"})}

    def test_naive_dseparation_algorithm(self):
        adjustment_sets = identify_backdoor(
            nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")]),
            ["X"],
            ["Y"],
            ["X", "Y", "Z"],
            BackdoorAdjustment.BACKDOOR_MIN,
            dseparation_algo="naive",
        )

        assert len(adjustment_sets) == 1
        assert set(adjustment_sets[0].get_adjustment_variables()) == {"Z"}

    def test_unsupported_dseparation_algorithm_raises(self):
        with pytest.raises(ValueError, match="is not supported"):
            identify_backdoor(
                nx.DiGraph([("X", "Y")]),
                ["X"],
                ["Y"],
                ["X", "Y"],
                BackdoorAdjustment.BACKDOOR_DEFAULT,
                dseparation_algo="unknown",
            )

    def test_unsupported_backdoor_method_raises(self):
        with pytest.raises(ValueError, match="not supported"):
            identify_backdoor(
                nx.DiGraph([("X", "Y")]),
                ["X"],
                ["Y"],
                ["X", "Y"],
                "unknown-method",
            )


class TestIdentifyFrontdoor:
    def test_finds_valid_frontdoor_variable(self):
        graph = nx.DiGraph([("X", "M"), ("M", "Y"), ("U", "X"), ("U", "Y")])

        assert identify_frontdoor(graph, ["X"], ["Y"], ["X", "M", "Y"]) == ["M"]

    def test_returns_empty_when_no_frontdoor_exists(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        assert identify_frontdoor(graph, ["X"], ["Y"], ["X", "Y", "Z"]) == []

    def test_unsupported_dseparation_algorithm_raises(self):
        with pytest.raises(ValueError, match="is not supported"):
            identify_frontdoor(
                nx.DiGraph([("X", "Y")]),
                ["X"],
                ["Y"],
                ["X", "Y"],
                dseparation_algo="unknown",
            )

    @pytest.mark.xfail(
        strict=True,
        reason="identify_frontdoor references cond1_graph in the naive branch, which is only assigned for the default branch",
    )
    def test_naive_dseparation_algorithm_is_supported(self):
        graph = nx.DiGraph([("X", "M"), ("M", "Y"), ("U", "X"), ("U", "Y")])

        assert identify_frontdoor(
            graph, ["X"], ["Y"], ["X", "M", "Y"], dseparation_algo="naive"
        ) == ["M"]


class TestIdentifyMediation:
    def test_multiple_mediators_are_returned_sorted(self):
        graph = nx.DiGraph(
            [("X", "M2"), ("X", "M1"), ("M1", "Y"), ("M2", "Y")]
        )

        assert identify_mediation(graph, ["X"], ["Y"]) == ["M1", "M2"]

    def test_node_not_on_a_directed_path_is_not_a_mediator(self):
        graph = nx.DiGraph([("X", "M1"), ("M1", "Y"), ("X", "M2")])

        assert identify_mediation(graph, ["X"], ["Y"]) == ["M1"]

    def test_no_mediators_returns_empty_list(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        assert identify_mediation(graph, ["X"], ["Y"]) == []
